    + '#ad2-tag{position:fixed;left:0;right:0;top:20px;z-index:2147483600;text-align:center;font:800 12px system-ui;letter-spacing:1.2px;color:rgba(226,232,240,.7);text-transform:uppercase}';
  document.head.appendChild(s);
  const t = document.createElement('div'); t.id = 'ad2-tag'; t.textContent = 'Simulation · 5 %/an, non garantie'; document.body.appendChild(t);
  nav('objectif');
  setTimeout(() => { window.scrollTo({ top: 0, behavior: 'instant' }); const sl = document.getElementById('obj-slider'); if (sl) { sl.value = 0; try { updateObjSlider(0); } catch (e) {} } }, 250);
