(async () => {
  document.getElementById('ad2-nocap')?.remove();
  const h = document.getElementById('ad2-hook'); if (h) { h.style.transition = 'opacity .35s'; h.style.opacity = '0'; setTimeout(() => h.remove(), 400); }
  const sl = document.getElementById('obj-slider'); if (!sl) return;
  await new Promise(r => setTimeout(r, 450));
  for (let v = 0; v <= 100; v += 1) { sl.value = v; try { updateObjSlider(v); } catch (e) {} await new Promise(r => setTimeout(r, 52 - v * 0.25)); }
})()

(() => {
  const b = document.getElementById('obj-badge-box'); if (b) { b.style.transition = 'transform .35s cubic-bezier(.2,1.6,.4,1), box-shadow .35s'; b.style.transform = 'scale(1.06)'; b.style.boxShadow = '0 0 0 3px rgba(74,222,128,.55), 0 10px 30px rgba(34,197,94,.35)'; }
})()

